import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.Dnb1kVW5.js";const m=JSON.parse('{"title":"Models","description":"","frontmatter":{"title":"Models"},"headers":[],"relativePath":"docs/settings/models.md","filePath":"docs/settings/models.md","lastUpdated":1789194236000}'),r={name:"docs/settings/models.md"};function l(d,e,n,i,c,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h1><p>Settings → Models is where you choose what powers chat and analysis in Orby. See <a href="/orby-releases/docs/concepts/llm-models">LLM models</a> for the concept; this page covers the settings themselves.</p><h2 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h2><p>Orby can run a model directly on your machine, in a few different sizes. A suitable size is suggested based on your hardware, and it&#39;s downloaded the first time it&#39;s needed — see <a href="/orby-releases/docs/getting-started/install-orby">Install Orby</a> for what to expect the first time.</p><h2 id="cloud-models" tabindex="-1">Cloud models <a class="header-anchor" href="#cloud-models" aria-label="Permalink to &quot;Cloud models&quot;">​</a></h2><p>You can instead (or additionally) connect a cloud model via a standard API endpoint. This is entirely optional — Orby works fully offline with a local model.</p><h2 id="trusted-vs-untrusted" tabindex="-1">Trusted vs. untrusted <a class="header-anchor" href="#trusted-vs-untrusted" aria-label="Permalink to &quot;Trusted vs. untrusted&quot;">​</a></h2><p>Your main, trusted model is the one with access to your actual project data. You can separately configure untrusted supporting models for other backend tasks — these are never given access to your data.</p><h2 id="before-you-rely-on-a-model" tabindex="-1">Before you rely on a model <a class="header-anchor" href="#before-you-rely-on-a-model" aria-label="Permalink to &quot;Before you rely on a model&quot;">​</a></h2><p>Use <a href="/orby-releases/docs/tools/model-test">Model Test</a> to confirm a newly configured model works correctly with Orby, and <a href="/orby-releases/docs/tools/model-benchmark">Model Benchmark</a> to compare how well and how fast different models answer real finance questions.</p>',10)])])}const f=o(r,[["render",l]]);export{m as __pageData,f as default};
